// A year is a leap year if it divides by 4, but not by 100 unless it divides by 400.
module main

import math

fn is_leap_year(year int) bool {
	divisible_by := fn [year] (n int) bool {
		return year % n == 0
	}
	return divisible_by(4) && (!divisible_by(100) || divisible_by(400))
}

